def calculate_change(pp: float, cash: float) -> str:
    cents = round(cash * 100) - round(pp * 100)  # 先各自转成整数分，避免浮点误差
    if cents < 0:
        return "ERROR"
    if cents == 0:
        return "ZERO"
    denoms = [(10000, "One Hundred"), (5000, "Fifty"), (2000, "Twenty"), (1000, "Ten"),
              (500, "Five"), (200, "Two"), (100, "One"), (50, "Half Dollar"),
              (25, "Quarter"), (10, "Dime"), (5, "Nickel"), (1, "Penny")]
    out = []
    for v, name in denoms:
        k, cents = divmod(cents, v)
        out += [name] * k
    return ",".join(sorted(out))


if __name__ == "__main__":
    print(calculate_change(230.0, 500.0))
